String letters = 'abc';
List<String> keepEmpty = letters.split('', -1);
System.assertEquals(4, keepEmpty.size());
System.assertEquals('a', keepEmpty.get(0));
System.assertEquals('b', keepEmpty.get(1));
System.assertEquals('c', keepEmpty.get(2));
System.assertEquals('', keepEmpty.get(3));
List<String> trimTrailing = letters.split('');
System.assertEquals(3, trimTrailing.size());
System.assertEquals('a', trimTrailing.get(0));
System.assertEquals('c', trimTrailing.get(2));
List<String> limited = letters.split('', 2);
System.assertEquals(2, limited.size());
System.assertEquals('a', limited.get(0));
System.assertEquals('bc', limited.get(1));
List<String> noMatchEmpty = ''.split('x');
System.assertEquals(1, noMatchEmpty.size());
System.assertEquals('', noMatchEmpty.get(0));
List<String> startAnchor = letters.split('^');
System.assertEquals(1, startAnchor.size());
System.assertEquals('abc', startAnchor.get(0));
String word = 'abc';
List<String> wordBoundaryKeep = word.split('\b', -1);
System.assertEquals(2, wordBoundaryKeep.size());
System.assertEquals('abc', wordBoundaryKeep.get(0));
System.assertEquals('', wordBoundaryKeep.get(1));
List<String> wordBoundaryTrim = word.split('\b');
System.assertEquals(1, wordBoundaryTrim.size());
System.assertEquals('abc', wordBoundaryTrim.get(0));
Pattern emptyPattern = Pattern.compile('');
List<String> patternSplit = emptyPattern.split('Ωb', -1);
System.assertEquals(3, patternSplit.size());
System.assertEquals('Ω', patternSplit.get(0));
System.assertEquals('b', patternSplit.get(1));
System.assertEquals('', patternSplit.get(2));

